        "summary": "美国能源部4月10日宣布，从战略石油储备中出借848万桶原油给4家美国石油公司，这是2月28日伊朗战事以来Trump政府为平抑油价的第二批SPR释放。Trump同时力推谈判+释放SPR双管齐下，显示其不想油价过高影响通胀。",
