        "summary": "4月11日，美伊双方在巴基斯坦首都伊斯兰堡展开正式谈判，美方由副总统万斯率300人代表团，伊方由议长卡利巴夫率71人代表团参加。双方在铀浓缩、撤军、霍尔木兹等核心问题上分歧明显，但谈判本身已释放缓和信号。上千艘等待霍尔木兹海峡通行船只仍在观望。",
