        "summary": "4月11日凌晨，俄罗斯无人机袭击乌克兰敖德萨，造成2人死亡、多栋建筑受损。俄方暂无回应。美伊谈判之际俄乌冲突升温，显示地缘风险并非单线下行，全球地缘格局仍高度复杂。",
