        "summary": "4月11日智能电动汽车发展高层论坛（2026）上，华为靳玉志、地平线余凯、蔚来李斌、比亚迪廉玉波等产业链重磅人物同日发声。余凯：舱驾融合芯片方案'小龙虾'将上车，降本1500-4000元/辆；靳玉志：L3是自动驾驶必经阶段，2026年或为全球元年；李斌：电芯统一+芯片归一化，超千亿降本空间。",
